package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.getValueAsString(String defValue).
 * Note: Since ReaderBasedJsonParser is a protected internal class in Jackson,
 * we use JsonFactory to instantiate the parser.
 */
public class ReaderBasedJsonParser_getValueAsString_TriageGen1Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactory();
    }

    /**
     * Tests the case where the current token is a String and it is complete.
     * Coverage: _currToken == JsonToken.VALUE_STRING and !_tokenIncomplete.
     */
    @Test
    public void testGetValueAsString_WhenTokenIsValueStringAndComplete() throws IOException {
        String json = "\"hello\"";
        JsonParser parser = factory.createParser(new StringReader(json));

        JsonToken token = parser.nextToken();
        Assert.assertEquals(JsonToken.VALUE_STRING, token);

        String value = parser.getValueAsString("default");
        Assert.assertEquals("hello", value);
    }

    /**
     * Tests the case where the current token is a String and it was marked as incomplete.
     * This triggers the _finishString() logic.
     * Coverage: _currToken == JsonToken.VALUE_STRING and _tokenIncomplete == true.
     */
    @Test
    public void testGetValueAsString_WhenTokenIsValueStringAndIncomplete() throws IOException {
        // To simulate an incomplete token in a controlled way with a standard parser,
        // we rely on the fact that for strings, if the parser state had _tokenIncomplete set,
        // the method should call _finishString() and return the contents.
        // In standard Jackson flow, a single string in a StringReader won't leave _tokenIncomplete true
        // unless we use a custom Reader that returns EOF prematurely.

        String json = "\"incomplete\"";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken();
        String value = parser.getValueAsString("default");

        Assert.assertEquals("incomplete", value);
    }

    /**
     * Tests the case where the current token is NOT a String (e.g., a Number).
     * This should trigger the super.getValueAsString(defValue) call.
     * Coverage: _currToken != JsonToken.VALUE_STRING.
     */
    @Test
    public void testGetValueAsString_WhenTokenIsNotValueString() throws IOException {
        String json = "123";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());

        // For non-string tokens, super.getValueAsString(defValue) typically returns defValue
        String value = parser.getValueAsString("default_val");
        Assert.assertEquals("default_val", value);
    }

    /**
     * Tests the case where the current token is null (EOF).
     * Coverage: _currToken == JsonToken.NOT_AVAILABLE.
     */
    @Test
    public void testGetValueAsString_WhenTokenIsNull() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // END_OBJECT
        parser.nextToken(); // null (EOF)

        Assert.assertNull(parser.currentToken());

        String value = parser.getValueAsString("default_val");
        Assert.assertEquals("default_val", value);
    }

    /**
     * Tests the case where the current token is a Boolean.
     * Coverage: Branching logic for non-string tokens.
     */
    @Test
    public void testGetValueAsString_WhenTokenIsBoolean() throws IOException {
        String json = "true";
        JsonParser parser = factory.createParser(new StringReader(json));

        parser.nextToken();
        Assert.assertEquals(JsonToken.VALUE_TRUE, parser.currentToken());

        String value = parser.getValueAsString("default_val");
        Assert.assertEquals("default_val", value);
    }
}
